    answer = lastAns.realcontent;
}
else if(uiLogic.default.msg) {
    answer = uiLogic.default.msg.realcontent;
}
 if(answer) {
    if (ibiz.util.jsonUtil) {
        console.log('jsonUtil解析数据：',  ibiz.util.jsonUtil.parseJson(answer));
    }
     if (answer && typeof answer == 'string') {
        var ret ={
                success: false,
                data: null,
                data_type: 'unknown',
                raw_content: null,
                message: '未找到有效的JSON或JSONArray内容'
            };
       // 定义匹配模式，按优先级排序
        const patterns = [
            {
                pattern: /```json\s*([\s\S]*?)\s*```/,  // Markdown JSON代码块
                cleanFn: (content) => content.replace(/```json|```/g, '').trim()
            },
            {
                pattern: /```\s*([\s\S]*?)\s*```/,      // 普通代码块
                cleanFn: (content) => content.replace(/```/g, '').trim()
            },
            {
                pattern: /\{[\s\S]*?\}(?=\s*[\n\r]|$)/, // 独立JSON对象
                cleanFn: (content) => content.trim()
            },
            {
                pattern: /\[[\s\S]*?\](?=\s*[\n\r]|$)/,  // 独立JSON数组
                cleanFn: (content) => content.trim()
            }
        ];

        for (const { pattern, cleanFn } of patterns) {
            const match = answer.match(pattern);
            if (match) {
                try {
                    let content = match[0];
                    content = cleanFn(content);

                    // 解析JSON
                    const parsed = JSON.parse(content);

                    // 判断类型
                    const jspn_type = Array.isArray(parsed) ? 'jsonarray' : 'jsonobject';
                    ret = {
                            success: true,
                            principal_id : view.parentView.context.work_item,
                            register_date : new Date(),
                            duration : 0,
                            name : 'unknown',
                            data: parsed,
                            data_type: jspn_type,
                            raw_content: content,
                            message: `成功提取${jspn_type === 'jsonarray' ? 'JSON数组' : 'JSON对象'}`
                        };
                    break;
                } catch (error) {
                    // 当前模式匹配但解析失败，继续尝试下一个模式
                    continue;
                }
            }
        }

       console.info(ret);

        if(ret.success && ret.data) {
            uiLogic.result=ret;
        }
    }
}

